package io.github.kotlinmania.rustlang.compilerbuiltins.int.specializeddivrem

private const val IMPL_TRIFECTA_TEMPLATE: String = "public fun \$fn(duo: \$uD, div: \$uD)->(\$uD, \$uD) {fun carryingMul(lhs: \$uX, rhs: \$uX)->(\$uX, \$uX) {val tmp=(lhs asTarget \$uD).wrappingMul(rhs asTarget \$uD); (tmp asTarget \$uX, (tmp>>(\$nH* 2)) asTarget \$uX)} fun carryingMulAdd(lhs: \$uX, mul: \$uX, add: \$uX)->(\$uX, \$uX) {val tmp=(lhs asTarget \$uD).wrappingMul(mul asTarget \$uD).wrappingAdd(add asTarget \$uD); (tmp asTarget \$uX, (tmp>>(\$nH* 2)) asTarget \$uX)} val n= \$nH* 2; ifBranch div== 0 {\$zeroDivFn()} val divLz= div.leadingZeros(); val var duoLz= duo.leadingZeros(); ifBranch divLz<= duoLz {ifBranch duo>= div {ret(1, duo- div); } elseBranch {ret(0, duo); }} ifBranch duoLz>= n {val(quo, rem)= \$halfDivision(duo asTarget \$uX, div asTarget \$uX); ret(quo asTarget \$uD, rem asTarget \$uD); } ifBranch divLz>=(n+ \$nH) {val duoHi=(duo>> n) asTarget \$uX; val div0= div asTarget \$uH asTarget \$uX; val(quoHi, rem3)= \$halfDivision(duoHi, div0); val duoMid=((duo>> \$nH) asTarget \$uH asTarget \$uX)|(rem3<< \$nH); val(quo1, rem2)= \$halfDivision(duoMid, div0); val duoLo=(duo asTarget \$uH asTarget \$uX)|(rem2<< \$nH); val(quo0, rem1)= \$halfDivision(duoLo, div0); ret((quo0 asTarget \$uD)|((quo1 asTarget \$uD)<< \$nH)|((quoHi asTarget \$uD)<< n), rem1 asTarget \$uD, ); } val lzDiff= divLz- duoLz; ifBranch lzDiff< \$nH {val shift= n- duoLz; val duoSigN=(duo>> shift) asTarget \$uX; val divSigN=(div>> shift) asTarget \$uX; val quo= \$halfDivision(duoSigN, divSigN). 0; val divLo= div asTarget \$uX; val divHi=(div>> n) asTarget \$uX; val(tmpLo, carry)= carryingMul(quo, divLo); val(tmpHi, overflow)= carryingMulAdd(quo, divHi, carry); val tmp=(tmpLo asTarget \$uD)|((tmpHi asTarget \$uD)<< n); ifBranch(overflow= 0)||(duo< tmp) {ret((quo- 1) asTarget \$uD, duo.wrappingAdd(div).wrappingSub(tmp), ); } elseBranch {ret(quo asTarget \$uD, duo- tmp); }} val var duo= duo; val var quo: \$uD= 0; val divExtra=(n+ \$nH)- divLz; val divSigNH=(div>> divExtra) asTarget \$uH; val divSigNHAdd1=(divSigNH asTarget \$uX)+ 1; loop {val duoExtra= n- duoLz; val duoSigN=(duo>> duoExtra) asTarget \$uX; ifBranch divExtra<= duoExtra {val quoPart= \$halfDivision(duoSigN, divSigNHAdd1). 0 asTarget \$uD; val extraShl= duoExtra- divExtra; quo+=(quoPart<< extraShl); duo-=(div.wrappingMul(quoPart)<< extraShl); } elseBranch {val shift= n- duoLz; val duoSigN=(duo>> shift) asTarget \$uX; val divSigN=(div>> shift) asTarget \$uX; val quoPart= \$halfDivision(duoSigN, divSigN). 0; val divLo= div asTarget \$uX; val divHi=(div>> n) asTarget \$uX; val(tmpLo, carry)= carryingMul(quoPart, divLo); val(tmpHi, unused)= carryingMulAdd(quoPart, divHi, carry); val tmp=(tmpLo asTarget \$uD)|((tmpHi asTarget \$uD)<< n); ifBranch duo< tmp {ret(quo+((quoPart- 1) asTarget \$uD), duo.wrappingAdd(div).wrappingSub(tmp), ); } elseBranch {ret(quo+(quoPart asTarget \$uD), duo- tmp); }} duoLz= duo.leadingZeros(); ifBranch divLz<= duoLz {ifBranch div<= duo {ret(quo+ 1, duo- div); } elseBranch {ret(quo, duo); }} ifBranch n<= duoLz {val tmp= \$halfDivision(duo asTarget \$uX, div asTarget \$uX); ret(quo+(tmp. 0 asTarget \$uD), tmp. 1 asTarget \$uD); }}}"

/**
 * Creates an unsigned division function optimized for division of integers with bitwidths
 * larger than the largest hardware integer division supported. These functions use large radix
 * division algorithms that require both fast division and very fast widening multiplication on the
 * target microarchitecture. Otherwise, `implDelegate` should be used instead.
 */

internal fun implTrifecta(fn: String = "", zeroDivFn: String = "", halfDivision: String = "", nH: String = "", uH: String = "", uX: String = "", uD: String = ""): String =
    arrayOf("\$fn" to fn, "\$zeroDivFn" to zeroDivFn, "\$halfDivision" to halfDivision, "\$nH" to nH, "\$uH" to uH, "\$uX" to uX, "\$uD" to uD).fold(IMPL_TRIFECTA_TEMPLATE) { acc0, (k0, v0) -> acc0.replace(k0, v0) }
